-- 014_student_core_and_timetable_links.sql
-- Generated from allstudentsatstart.csv (core student data) and timetablestudents.csv (group memberships)

-- A few extra SIMS-export fields not yet in the schema
ALTER TABLE students ADD COLUMN IF NOT EXISTS admission_number TEXT;
ALTER TABLE students ADD COLUMN IF NOT EXISTS birth_certificate_seen TEXT;
ALTER TABLE students ADD COLUMN IF NOT EXISTS restaurant TEXT;
ALTER TABLE students ADD COLUMN IF NOT EXISTS swimming_paid BOOLEAN;

-- 1. Students (upsert on UPN, which is already UNIQUE)

-- 2. Any teaching-group codes referenced by students but not already in `classes` (new sets not covered by the original TBTR export, or naming variants) get created here

-- 3. Link each student to their teaching groups
DELETE FROM student_class WHERE student_id IN (SELECT student_id FROM students WHERE upn IS NOT NULL);
